let deck = [{ rank: "A", suit: "S", value: 11 }, { rank: "2", suit: "S", value: 2 }, { rank: "3", suit: "S", value: 3 }, { rank: "4", suit: "S", value: 4 }, { rank: "5", suit: "S", value: 5 }, { rank: "6", suit: "S", value: 6 }, { rank: "7", suit: "S", value: 7 }, { rank: "8", suit: "S", value: 8 }, { rank: "9", suit: "S", value: 9 }, { rank: "10", suit: "S", value: 10 }, { rank: "J", suit: "S", value: 10 }, { rank: "Q", suit: "S", value: 10 }, { rank: "K", suit: "S", value: 10 }, { rank: "A", suit: "H", value: 11 }, { rank: "2", suit: "H", value: 2 }, { rank: "3", suit: "H", value: 3 }, { rank: "4", suit: "H", value: 4 }, { rank: "5", suit: "H", value: 5 }, { rank: "6", suit: "H", value: 6 }, { rank: "7", suit: "H", value: 7 }, { rank: "8", suit: "H", value: 8 }, { rank: "9", suit: "H", value: 9 }, { rank: "10", suit: "H", value: 10 }, { rank: "J", suit: "H", value: 10 }, { rank: "Q", suit: "H", value: 10 }, { rank: "K", suit: "H", value: 10 }, { rank: "A", suit: "D", value: 11 }, { rank: "2", suit: "D", value: 2 }, { rank: "3", suit: "D", value: 3 }, { rank: "4", suit: "D", value: 4 }, { rank: "5", suit: "D", value: 5 }, { rank: "6", suit: "D", value: 6 }, { rank: "7", suit: "D", value: 7 }, { rank: "8", suit: "D", value: 8 }, { rank: "9", suit: "D", value: 9 }, { rank: "10", suit: "D", value: 10 }, { rank: "J", suit: "D", value: 10 }, { rank: "Q", suit: "D", value: 10 }, { rank: "K", suit: "D", value: 10 }, { rank: "A", suit: "C", value: 11 }, { rank: "2", suit: "C", value: 2 }, { rank: "3", suit: "C", value: 3 }, { rank: "4", suit: "C", value: 4 }, { rank: "5", suit: "C", value: 5 }, { rank: "6", suit: "C", value: 6 }, { rank: "7", suit: "C", value: 7 }, { rank: "8", suit: "C", value: 8 }, { rank: "9", suit: "C", value: 9 }, { rank: "10", suit: "C", value: 10 }, { rank: "J", suit: "C", value: 10 }, { rank: "Q", suit: "C", value: 10 }, { rank: "K", suit: "C", value: 10 }];

// A hand's total: aces count 11, or 1 if 11 would go over 21
function aces(cards) = count(cards, c => c.rank == "A");
function score(cards) =
  sum(map(cards, c => c.value)) - 10 * min([
    aces(cards),
    max([0, ceil((sum(map(cards, c => c.value)) - 21) / 10)])
  ]);

// A player with one more card
function drawn(p, card) = {
  id: p.id,
  name: p.name,
  cards: p.cards + [card],
  total: score(p.cards + [card]),
  state: score(p.cards + [card]) > 21 ? "bust" : "playing"
};

// A player who has stood
function stood(p) = {
  id: p.id,
  name: p.name,
  cards: p.cards,
  total: p.total,
  state: "stood"
};

// The winner of a finished game: the highest total that isn't bust
function beats(x, y) = x.state != "bust" && (y.state == "bust" || x.total > y.total);
function winner(ps) = beats(ps[0], ps[1]) ? ps[0].id : (beats(ps[1], ps[0]) ? ps[1].id : null);
